    /// Install tools using Kahn's algorithm for dependency ordering.
    /// Returns (successful_installations, failed_installations, attempted_failures).
    /// The final collection excludes tools blocked before their installer was spawned.
    async fn install_with_deps(
        &self,
        config: &Arc<Config>,
        versions: Vec<ToolRequest>,
        opts: &InstallOptions,
        install_progress: Option<&dyn InstallProgress>,
    ) -> (
        Vec<ToolVersion>,
        Vec<(ToolRequest, eyre::Error)>,
        Vec<ToolRequest>,
    ) {
        if versions.is_empty() {
            return (vec![], vec![], vec![]);
        }

        // Build index map to preserve original request order
        let request_order: HashMap<String, usize> = versions
            .iter()
            .enumerate()
            .map(|(i, tr)| (tool_key(tr), i))
            .collect();

        // Build dependency graph
        let tool_deps = match ToolDeps::new(versions.clone()) {
            Ok(deps) => Arc::new(Mutex::new(deps)),
            Err(e) => {
                // If we can't build the graph, return error for all versions
                let failed: Vec<_> = versions
                    .into_iter()
                    .map(|tr| (tr, eyre::eyre!("Failed to build dependency graph: {}", e)))
                    .collect();
                return (vec![], failed, vec![]);
            }
        };

        // Tell the display which tools are held behind which, before anything
        // starts, so a row can say "waiting for node" instead of nothing.
        if let Some(progress) = install_progress {
            let deps = tool_deps.lock().await;
            for tr in &versions {
                let pending = deps.pending_dependencies(tr);
                if !pending.is_empty() {
                    progress.set_waiting(&tool_key(tr), pending);
                }
            }
        }

        let mut rx = tool_deps.lock().await.subscribe();

        let raw = opts.raw || Settings::get().raw;
        let jobs = match raw {
            true => 1,
            false => crate::jobs::resolve(Settings::get().jobs, opts.jobs),
        };
        let semaphore = Arc::new(Semaphore::new(jobs));
        let ts = Arc::new(self.clone());
        let opts = Arc::new(opts.clone());

        let mut installed = vec![];
        let mut failed = vec![];
        let mut attempted_failures = vec![];
        let mut jset: JoinSet<(ToolRequest, Result<ToolVersion>)> = JoinSet::new();
        // Track in-flight tools to recover from task panics
        let mut in_flight: HashMap<tokio::task::Id, ToolRequest> = HashMap::new();

        loop {
            tokio::select! {
                // Use `biased` to ensure completed installations are handled before starting new ones.
                // This priority ordering ensures dependency tracking stays correct: we must process
                // completions (which may unblock dependents) before spawning new installations.
                biased;

                // Handle completed installations first (higher priority)
                Some(result) = jset.join_next() => {
                    let mpr = MultiProgressReport::get();
                    match result {
                        Ok((tr, Ok(tv))) => {
                            mpr.footer_inc(1);
                            installed.push(tv);
                            tool_deps.lock().await.complete_success(&tr);
                        }
                        Ok((tr, Err(e))) => {
                            mpr.footer_inc(1);
                            attempted_failures.push(tr.clone());
                            failed.push((tr.clone(), e));
                            tool_deps.lock().await.complete_failure(&tr);
                        }
                        Err(e) => {
                            // Task panicked - try to recover the tool request from in_flight tracking
                            mpr.footer_inc(1);
                            if let Some(tr) = in_flight.remove(&e.id()) {
                                attempted_failures.push(tr.clone());
                                failed.push((tr.clone(), eyre::eyre!("Installation task panicked: {e:#}")));
                                tool_deps.lock().await.complete_failure(&tr);
                            } else {
                                warn!("Task panicked but tool request not found: {e:#}");
                            }
                        }
                    }
                }

                // Receive new tools to install
                Some(maybe_tr) = rx.recv() => {
                    match maybe_tr {
                        Some(tr) => {
                            // Spawn installation task
                            let permit = match semaphore.clone().acquire_owned().await {
                                Ok(p) => p,
                                Err(e) => {
                                    // Mark as failed and notify tool_deps so dependents are blocked
                                    MultiProgressReport::get().footer_inc(1);
                                    failed.push((tr.clone(), eyre::eyre!("Failed to acquire semaphore: {}", e)));
                                    tool_deps.lock().await.complete_failure(&tr);
                                    continue;
                                }
                            };

                            let config = config.clone();
                            let ts = ts.clone();
                            let opts = opts.clone();
                            let tr_clone = tr.clone();

                            let progress = install_progress.and_then(|p| p.start_tool(&tool_key(&tr)));
                            let handle = jset.spawn(async move {
                                let _permit = permit;
                                let result = Self::install_single_tool(&config, &ts, &tr, &opts, progress.as_deref()).await;
                                if let Some(progress) = progress {
                                    let error = result.as_ref().err().map(|e| e.to_string());
                                    progress.complete(error.as_deref());
                                }
                                (tr, result)
                            });
                            in_flight.insert(handle.id(), tr_clone);
                        }
                        None => {
                            // All tools have been emitted, wait for remaining tasks
                            break;
                        }
                    }
                }

                else => break,
            }
        }

        // Wait for all remaining tasks to complete
        while let Some(result) = jset.join_next().await {
            let mpr = MultiProgressReport::get();
            match result {
                Ok((tr, Ok(tv))) => {
                    mpr.footer_inc(1);
                    installed.push(tv);
                    tool_deps.lock().await.complete_success(&tr);
                }
                Ok((tr, Err(e))) => {
                    mpr.footer_inc(1);
                    attempted_failures.push(tr.clone());
                    failed.push((tr.clone(), e));
                    tool_deps.lock().await.complete_failure(&tr);
                }
                Err(e) => {
                    mpr.footer_inc(1);
                    if let Some(tr) = in_flight.remove(&e.id()) {
                        attempted_failures.push(tr.clone());
                        failed.push((tr.clone(), eyre::eyre!("Installation task panicked: {e:#}")));
                        tool_deps.lock().await.complete_failure(&tr);
                    } else {
                        warn!("Task panicked but tool request not found: {e:#}");
                    }
                }
            }
        }

        // Add blocked tools to failures
        let blocked = tool_deps.lock().await.blocked_tools();
        for tr in blocked {
            failed.push((tr.clone(), eyre::eyre!("Skipped due to failed dependency")));
            MultiProgressReport::get().footer_inc(1);
        }

        // Sort installed versions by original request order to preserve user's intended ordering
        installed.sort_by_key(|tv| {
            let key = tool_key(&tv.request);
            request_order.get(&key).copied().unwrap_or(usize::MAX)
        });

        (installed, failed, attempted_failures)
    }

    /// Install a single tool
    async fn install_single_tool(
        config: &Arc<Config>,
        ts: &Arc<Toolset>,
        tr: &ToolRequest,
        opts: &Arc<InstallOptions>,
        tool_progress: Option<&dyn ToolProgress>,
    ) -> Result<ToolVersion> {
        let mpr = MultiProgressReport::get();
        let pre_resolve_backend = tr.backend()?;
        backend::ensure_backend_enabled(&pre_resolve_backend.get_type())?;
        let mut resolve_options = opts.resolve_options.clone();
        if should_refresh_remote_versions(tr, &pre_resolve_backend, &resolve_options) {
            resolve_options.refresh_remote_versions = true;
        }
        let mut tv = tr.resolve(config, &resolve_options).await?;
        let backend = tv.backend()?;
        backend::ensure_backend_enabled(&backend.get_type())?;
        if let Some(dir) = &opts.install_dir {
            let tool_dir_name = tv.ba().tool_dir_name();
            tv.install_path = Some(dir.join(tool_dir_name).join(tv.tv_pathname()));
            tv.install_path_is_explicit = true;
        }
        let before_date = transitive_dependency_before_date(tr, &tv);

        let ctx = InstallContext {
            config: config.clone(),
            ts: ts.clone(),
            pr: if let Some(progress) = tool_progress {
                progress.set_prefix(tv.style());
                progress.reporter()
            } else {
                mpr.add_with_options(&tv.style(), opts.dry_run)
            },
            force: opts.force,
            dry_run: opts.dry_run,
            locked: config.invocation_locked_for(tr.source(), opts.locked)
                || config.tool_config_locked(tr.source()),
            before_date,
            dependency_context: OnceCell::new(),
        };

    /// Connect backend install command stdin/stdout/stderr directly to the terminal.
    /// Implies `--jobs=1`
    #[usage(long, overrides = "jobs")]
    raw: bool,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum PruneMode {
    None,
    Immediate,
    Deferred(Duration),
}

impl Upgrade {
    pub(super) fn is_dry_run(&self) -> bool {
        self.dry_run || self.dry_run_code
    }

    /// How versions upgraded away from should be handled. Either flag wins over
    /// the settings, and `overrides_with` makes the later flag win.
    fn prune_mode(&self) -> Result<PruneMode> {
        if self.prune {
            return Ok(PruneMode::Immediate);
        }
        if self.no_prune || !Settings::get().upgrade.auto_prune {
            return Ok(PruneMode::None);
        }
        Ok(PruneMode::Deferred(
            Settings::get().upgrade_prune_after_duration()?,
        ))
    }

    fn scope(&self) -> ConfigScope {
        if self.local {
            ConfigScope::LocalOnly
        } else {
            ConfigScope::All
        }
    }

    pub(crate) async fn run(mut self) -> Result<()> {
        if self.legacy_bump {
            deprecated_at!(
                "2026.8.5",
                "2027.8.5",
                "cli.upgrade.bump-l",
                "`mise upgrade -l` is deprecated. Use `mise upgrade -b` or `mise upgrade --bump` instead. After removal, `-l` will become shorthand for `--local`."
            );
            self.bump = true;
        }
        if self.monorepo {
            unimplemented!("mise upgrade --monorepo is not implemented yet");
        }
        let mut config = Config::get().await?;
        if !self.is_dry_run() {
            crate::lockfile::migrate_monorepo_lockfiles(&config, false)?;
        }
        let ts = ToolsetBuilder::new()
            .with_args(&self.tool)
            .with_scope(self.scope())
            .build(&config)
            .await?;
        // Compute before_date once to ensure consistency when using relative durations
        let before_date = self.get_before_date()?;
        let opts = ResolveOptions {
            use_locked_version: false,
            latest_versions: true,
            resolve_rolling_channels: false,
            prefer_exact_version: false,
            before_date,
            before_date_from_default: false,
            filter_installed_versions_by_release_date: false,
            offline: false,
            refresh_remote_versions: false,
            inactive: self.inactive,
        };
        // Filter tools to check before doing expensive version lookups
        let filter_tools = if !self.interactive && !self.tool.is_empty() {
            Some(self.tool.as_slice())
        } else {
            None
        };
        let exclude_tools = if !self.exclude.is_empty() {
            Some(self.exclude.as_slice())
        } else {
            None
        };
        let mut outdated = ts
            .list_outdated_versions_filtered(&config, self.bump, &opts, filter_tools, exclude_tools)
            .await;
        self.warn_if_newer_versions_hidden_by_minimum_release_age(
            &config,
            &ts,
            &opts,
            filter_tools,
            exclude_tools,
        )
        .await;
        if self.interactive && !outdated.is_empty() {
            outdated = self.get_interactive_tool_set(&outdated)?;
            if outdated.is_empty() {
                return Ok(());
            }
        }
        if outdated.is_empty() {
            let bump_outdated = if self.bump {
                Vec::new()
            } else {
                ts.list_outdated_versions_filtered(
                    &config,
                    true,
                    &opts,
                    filter_tools,
                    exclude_tools,
                )
                .await
                .into_iter()
                .filter(|o| o.bump.is_some())
                .collect::<Vec<_>>()
            };
            if bump_outdated.is_empty() {
                info!("All tools are up to date");
            } else {
                let hidden = bump_outdated.len().saturating_sub(MAX_OUT_OF_RANGE_UPDATES);
                let mut updates = bump_outdated
                    .iter()
                    .take(MAX_OUT_OF_RANGE_UPDATES)
                    .map(|o| {
                        let current = o.current.as_deref().unwrap_or("MISSING");
                        format!("  {} {} → {} ({})", o.name, current, o.latest, o.source)
                    })
                    .collect::<Vec<_>>()
                    .join("\n");
                if hidden > 0 {
                    updates.push_str(&format!("\n  … and {hidden} more"));
                }
                info!(
                    "Newer versions are available but do not match the configured version ranges:\n{updates}\nRun `mise outdated --bump` to view all, or `mise upgrade --bump` to update the configuration and upgrade."
                );
            }
        } else {
                use crate::toolset::outdated_info::compute_config_bumps;
                let tool_versions: Vec<(String, String)> = self
                    .tool
                    .iter()
                    .filter_map(|t| {
                        t.tvr
                            .as_ref()
                            .map(|tvr| (t.ba.short.clone(), tvr.version()))
                    })
                    .collect();
                let refs: Vec<(&str, &str)> = tool_versions
                    .iter()
                    .map(|(n, v)| (n.as_str(), v.as_str()))
                    .collect();
                let bumps = compute_config_bumps(config, &refs);
                for bump in &bumps {
                    miseprintln!(
                        "Would update {} from {} to {} in {}",
                        bump.tool_name,
                        bump.old_version,
                        bump.new_version,
                        display_path(&bump.config_path)
                    );
                }
            }
            if self.dry_run_code {
                return Err(exit::request(1));
            }
            return Ok(());
        }

        let opts = InstallOptions {
            reason: "upgrade".to_string(),
            force: false,
            jobs: self.jobs,
            raw: self.raw,
            resolve_options: ResolveOptions {
                use_locked_version: false,
                latest_versions: true,
                resolve_rolling_channels: false,
                prefer_exact_version: false,
                before_date,
                before_date_from_default: false,
                filter_installed_versions_by_release_date: false,
                offline: false,
                refresh_remote_versions: false,
                inactive: self.inactive,
            },
